import java.util.*;

public class Main {
  static void reject(String why) {
    System.err.println(why);
    System.exit(3);
  }

  public static void main(String[] args) {
    Scanner in = new Scanner(System.in);
    List<Long> xs = new ArrayList<>();
    while (in.hasNext()) {
      if (!in.hasNextLong()) reject("butun son kutilgan");
      xs.add(in.nextLong());
    }
    if (xs.size() != 2) reject("aynan ikkita son kutilgan");
    for (long x : xs) {
      if (x < 1 || x > 100) reject("1 <= a, b <= 100 buzildi: " + x);
    }
  }
}
